-- G7 event_premium_20d (Addendum 10): the two read-only queries that follow the builds, written 2026-10-30 before any run.
-- QUERY 1 (diagnostics): the stored table against ARM 0, and ARM 0 against ARM 1.
SELECT (SELECT COUNT(*) FROM events_ratio) AS stored_rows, (SELECT COUNT(*) FROM events_ratio_g7_arm0) AS arm0_rows, (SELECT COUNT(*) FROM events_ratio_g7_arm1) AS arm1_rows, (SELECT COUNT(*) FROM events_ratio_g7_arm0 a JOIN events_ratio s ON s.event_id = a.event_id AND s.ticker = a.ticker) AS arm0_in_both, (SELECT COUNT(*) FROM events_ratio_g7_arm0 a WHERE NOT EXISTS (SELECT 1 FROM events_ratio s WHERE s.event_id = a.event_id AND s.ticker = a.ticker)) AS only_in_arm0, (SELECT COUNT(*) FROM events_ratio s WHERE NOT EXISTS (SELECT 1 FROM events_ratio_g7_arm0 a WHERE a.event_id = s.event_id AND a.ticker = s.ticker)) AS only_in_stored, (SELECT COUNT(*) FROM events_ratio_g7_arm0 a JOIN events_ratio s ON s.event_id = a.event_id AND s.ticker = a.ticker WHERE ABS(a.scaled - s.scaled) > 0.000001 OR ABS(a.ratio - s.ratio) > 0.000001 OR a.m <> s.m OR a.bucket <> s.bucket) AS common_rows_that_differ, (SELECT COUNT(*) FROM events_ratio_g7_arm0 a WHERE EXISTS (SELECT 1 FROM event_exclusions x WHERE x.event_id = a.event_id AND x.severity = $$exclude$$)) AS arm0_rows_with_exclude_row, (SELECT COUNT(*) FROM events_ratio_g7_arm0 a WHERE NOT EXISTS (SELECT 1 FROM events_ratio_g7_arm1 b WHERE b.event_id = a.event_id AND b.ticker = a.ticker)) AS in_arm0_not_arm1;

-- QUERY 2 (results): the matched excess of the ordinary types by era and cohort for the stored table, ARM 0 and ARM 1, with the naive SE and an SE clustered by month.
WITH base_m AS (SELECT m, SUM(mm_matched * mm_n) / SUM(mm_n) AS mm_month FROM mm_matched GROUP BY m), src AS (SELECT $$1_stored$$ AS arm, er.event_id, er.m, er.scaled, er.ratio FROM events_ratio er WHERE er.bucket = $$a_all_other_types$$ UNION ALL SELECT $$2_arm0$$, er.event_id, er.m, er.scaled, er.ratio FROM events_ratio_g7_arm0 er WHERE er.bucket = $$a_all_other_types$$ UNION ALL SELECT $$3_arm1$$, er.event_id, er.m, er.scaled, er.ratio FROM events_ratio_g7_arm1 er WHERE er.bucket = $$a_all_other_types$$), j AS (SELECT s.arm, s.m, CASE WHEN s.m < $$2008-01-01$$ THEN $$2004-07$$ WHEN s.m < $$2013-01-01$$ THEN $$2008-12$$ WHEN s.m < $$2019-01-01$$ THEN $$2013-18$$ ELSE $$2019-26$$ END AS era, CASE WHEN s.event_id IN (SELECT id FROM new_events_20261015) THEN $$wave 1$$ WHEN s.event_id IN (SELECT id FROM new_events_wave2) THEN $$wave 2$$ ELSE $$older$$ END AS cohort, s.scaled - mm.mm_matched AS d FROM src s JOIN base_m ON base_m.m = s.m JOIN mm_matched mm ON mm.m = s.m AND mm.b = CASE WHEN s.ratio < 0.775 THEN 1 WHEN s.ratio < 0.950 THEN 2 WHEN s.ratio < 1.162 THEN 3 ELSE 4 END), g AS (SELECT arm, era, cohort, d, m FROM j UNION ALL SELECT arm, $$pooled 2004-18$$, cohort, d, m FROM j WHERE era <> $$2019-26$$), st AS (SELECT arm, era, cohort, COUNT(*) AS n, AVG(d) AS dbar, STDDEV(d) AS sd FROM g GROUP BY 1, 2, 3), cl AS (SELECT x.arm, x.era, x.cohort, SUM(x.s_m * x.s_m) AS ss FROM (SELECT g.arm, g.era, g.cohort, g.m, SUM(g.d - st.dbar) AS s_m FROM g JOIN st ON st.arm = g.arm AND st.era = g.era AND st.cohort = g.cohort GROUP BY 1, 2, 3, 4) x GROUP BY 1, 2, 3) SELECT st.arm, st.era, st.cohort, st.n, ROUND(st.dbar::numeric, 4) AS excess_matched, ROUND((st.sd / SQRT(st.n))::numeric, 4) AS se_naive, ROUND((SQRT(cl.ss) / st.n)::numeric, 4) AS se_clustered_by_month FROM st JOIN cl ON cl.arm = st.arm AND cl.era = st.era AND cl.cohort = st.cohort ORDER BY 1, 2, 3;
